INSERT INTO skills VALUES ('SKL-01','RESOURCE','RESOURCE 복구 절차 01','APPROVED','CPU utilization 96%, memory exhaustion and process queue saturation','관측 지표·의존성·승인 증적을 확인한다.','승인된 시연에서 가상 지표를 정상화하고 오류율을 재측정한다.','가상 자산에만 적용. 실제 운영 명령은 실행하지 않는다.',NULL,'seed-admin','2026-10-01 00:00:00');
